CREATE TEMP TABLE hs_seed_ward_catalog ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($hs_seed_wards$[{"city_id":"12","city":"Thành phố Hồ Chí Minh","ward_id":"24076","ward":"Phường Hạnh Thông"},{"city_id":"12","city":"Thành phố Hồ Chí Minh","ward_id":"24332","ward":"Phường An Nhơn"},{"city_id":"12","city":"Thành phố Hồ Chí Minh","ward_id":"24588","ward":"Phường Gò Vấp"}]$hs_seed_wards$::jsonb)
    AS w(city_id text, city text, ward_id text, ward text);
